	targetsFlag := fs.String("targets", "", "comma-separated target names")
	parallel := fs.Int("parallel", runtime.NumCPU(), "max concurrent target executions")
	noCache := fs.Bool("no-cache", false, "skip all cache lookups")
	reportPath := fs.String("report", "", "also write JSON report to this file")
	if err := fs.Parse(args); err != nil {
