func runBuild(configPath, targetsFlag string, parallel int, noCache bool, reportPath string) error {
	cfg, configDir, err := loadConfig(configPath)
	if err != nil {
		return err
	}
	targetMap, err := validateConfig(cfg)
	if err != nil {
		return err
	}
	requested, err := selectTargets(cfg, targetMap, targetsFlag)
	if err != nil {
		return err
	}
	order := topologicalOrder(cfg, requested)
	reverseDeps := buildReverseDeps(cfg, requested)

	cacheKeys := make(map[string]string)
	for i := range cfg.Targets {
		t := &cfg.Targets[i]
		if !requested[t.Name] {
			continue
		}
		key, err := computeCacheKey(t, configDir)
		if err != nil {
			return err
		}
		cacheKeys[t.Name] = key
	}

	executor := &buildExecutor{
		config:    cfg,
		configDir: configDir,
		cacheDir:  filepath.Join(configDir, ".buildctl-cache"),
		noCache:   noCache,
	}

	status := make(map[string]string)
	durations := make(map[string]int64)
	completed := 0
	total := len(requested)
	readyCh := make(chan *TargetConfig, total+1)
	resultCh := make(chan execResult, total+1)

	var wg sync.WaitGroup
	for i := 0; i < parallel; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for t := range readyCh {
				resultCh <- executor.execute(t)
			}
		}()
	}

	buildStart := time.Now()
	for i := range cfg.Targets {
		t := &cfg.Targets[i]
		if requested[t.Name] && len(uniqueStrings(t.Dependencies)) == 0 {
			readyCh <- t
		}
	}

	for completed < total {
		res := <-resultCh
		status[res.name] = res.status
		durations[res.name] = res.durationMS
		if res.cacheKey != "" {
			cacheKeys[res.name] = res.cacheKey
		}
		completed++

		if res.status == "built" || res.status == "cached" {
			for _, dependent := range reverseDeps[res.name] {
				if allDependenciesComplete(dependent, targetMap, requested, status) {
					readyCh <- targetMap[dependent]
				}
			}
		} else {
			markSkipped(reverseDeps, status, durations, &completed, res.name)
		}
	}

	close(readyCh)
	wg.Wait()

	report := BuildReport{Pipeline: cfg.Pipeline.Name, Targets: []BuildTargetReport{}}
	for _, name := range order {
		st := status[name]
		if st == "" {
			st = "skipped"
		}
		report.Targets = append(report.Targets, BuildTargetReport{
			Name:       name,
			Status:     st,
			Cached:     st == "cached",
			DurationMS: durations[name],
			CacheKey:   cacheKeys[name],
		})
	}

	summary := BuildSummary{Total: len(report.Targets)}
	for _, t := range report.Targets {
		switch t.Status {
		case "built":
			summary.Built++
		case "cached":
			summary.Cached++
		case "failed":
			summary.Failed++
		case "skipped":
			summary.Skipped++
		}
	}
	summary.DurationMS = time.Since(buildStart).Milliseconds()
	report.Summary = summary

	data, err := json.MarshalIndent(report, "", "  ")
	if err != nil {
		return err
	}
	fmt.Println(string(data))
	if reportPath != "" {
		if err := os.WriteFile(reportPath, data, 0644); err != nil {
			return err
		}
	}
	if summary.Failed > 0 {
		return fmt.Errorf("build failed")
	}
	return nil
}

func runGraph(configPath string) error {
	cfg, _, err := loadConfig(configPath)
	if err != nil {
		return err
	}
	if _, err := validateConfig(cfg); err != nil {
		return err
	}
	fmt.Printf("digraph %s {\n", strconv.Quote(cfg.Pipeline.Name))
	for _, t := range cfg.Targets {
		if len(uniqueStrings(t.Dependencies)) == 0 {
			fmt.Printf("  %s;\n", strconv.Quote(t.Name))
		}
	}
	for _, t := range cfg.Targets {
		for _, dep := range uniqueStrings(t.Dependencies) {
			fmt.Printf("  %s -> %s;\n", strconv.Quote(t.Name), strconv.Quote(dep))
		}
	}
	fmt.Println("}")
	return nil
}

func runClean(configPath string) error {
	abs, err := filepath.Abs(configPath)
	if err != nil {
		return err
	}
	cacheDir := filepath.Join(filepath.Dir(abs), ".buildctl-cache")
	return os.RemoveAll(cacheDir)
}

func runStatus(configPath string) error {
	cfg, configDir, err := loadConfig(configPath)
	if err != nil {
		return err
	}
	if _, err := validateConfig(cfg); err != nil {
		return err
	}
	cacheDir := filepath.Join(configDir, ".buildctl-cache")
	report := StatusReport{Targets: []StatusTarget{}}
	for i := range cfg.Targets {
		t := &cfg.Targets[i]
		key, err := computeCacheKey(t, configDir)
		if err != nil {
			return err
		}
		valid, entry, err := cacheValid(cacheDir, key, t.Outputs, configDir)
		if err != nil {
			return err
		}
		st := StatusTarget{Name: t.Name, Cached: valid}
		if valid {
			st.CacheKey = key
			st.CachedAt = entry.Timestamp
		}
		report.Targets = append(report.Targets, st)
	}
	data, err := json.MarshalIndent(report, "", "  ")
	if err != nil {
		return err
	}
	fmt.Println(string(data))
	return nil
}

func loadConfig(path string) (*Config, string, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return nil, "", err
	}
	var cfg Config
	if _, err := toml.DecodeFile(path, &cfg); err != nil {
		return nil, "", err
	}
	for i := range cfg.Targets {
		cfg.Targets[i].Dependencies = uniqueStrings(cfg.Targets[i].Dependencies)
		if cfg.Targets[i].Timeout <= 0 {
			cfg.Targets[i].Timeout = 300
		}
	}
	return &cfg, filepath.Dir(abs), nil
}

func validateConfig(cfg *Config) (map[string]*TargetConfig, error) {
	targetMap := map[string]*TargetConfig{}
	for i := range cfg.Targets {
		t := &cfg.Targets[i]
		if t.Name == "" {
			return nil, fmt.Errorf("target name is empty")
		}
		if _, ok := targetMap[t.Name]; ok {
			return nil, fmt.Errorf("duplicate target name %q", t.Name)
		}
		targetMap[t.Name] = t
	}

	for _, t := range targetMap {
		for _, dep := range t.Dependencies {
			if _, ok := targetMap[dep]; !ok {
				return nil, fmt.Errorf("target %q depends on missing target %q", t.Name, dep)
			}
		}
	}

	states := map[string]int{}
	var stack []string
	var dfs func(name string) error
	dfs = func(name string) error {
		states[name] = 1
		stack = append(stack, name)
		for _, dep := range targetMap[name].Dependencies {
			if states[dep] == 1 {
				idx := 0
				for i, s := range stack {
					if s == dep {
						idx = i
						break
					}
				}
				cycle := append([]string{}, stack[idx:]...)
				cycle = append(cycle, dep)
				return fmt.Errorf("cycle detected: %s", strings.Join(cycle, " -> "))
			}
			if states[dep] == 0 {
				if err := dfs(dep); err != nil {
					return err
				}
			}
		}
		stack = stack[:len(stack)-1]
		states[name] = 2
		return nil
	}

	names := make([]string, 0, len(targetMap))
	for n := range targetMap {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, n := range names {
		if states[n] == 0 {
			if err := dfs(n); err != nil {
				return nil, err
			}
		}
	}
	return targetMap, nil
}

func selectTargets(cfg *Config, targetMap map[string]*TargetConfig, targetsFlag string) (map[string]bool, error) {
	if strings.TrimSpace(targetsFlag) == "" {
		requested := map[string]bool{}
		for _, t := range cfg.Targets {
			requested[t.Name] = true
		}
		return requested, nil
	}

	requested := map[string]bool{}
	for _, part := range strings.Split(targetsFlag, ",") {
		name := strings.TrimSpace(part)
		if _, ok := targetMap[name]; !ok {
			return nil, fmt.Errorf("target %q not found", name)
		}
		var visit func(string)
		visit = func(n string) {
			if requested[n] {
				return
			}
			requested[n] = true
			for _, dep := range targetMap[n].Dependencies {
				visit(dep)
			}
		}
		visit(name)
	}
	return requested, nil
}

func topologicalOrder(cfg *Config, requested map[string]bool) []string {
	indeg := map[string]int{}
	for _, t := range cfg.Targets {
		if !requested[t.Name] {
			continue
		}
		count := 0
		for _, dep := range uniqueStrings(t.Dependencies) {
			if requested[dep] {
				count++
			}
		}
		indeg[t.Name] = count
	}

	queue := []string{}
	for _, t := range cfg.Targets {
		if requested[t.Name] && indeg[t.Name] == 0 {
			queue = append(queue, t.Name)
		}
	}

	order := []string{}
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		order = append(order, name)
		for _, t := range cfg.Targets {
			if !requested[t.Name] {
				continue
			}
			for _, dep := range uniqueStrings(t.Dependencies) {
				if dep == name {
					indeg[t.Name]--
					if indeg[t.Name] == 0 {
						queue = append(queue, t.Name)
					}
					break
				}
			}
		}
	}
	return order
}

func buildReverseDeps(cfg *Config, requested map[string]bool) map[string][]string {
	reverse := map[string][]string{}
	for _, t := range cfg.Targets {
		if !requested[t.Name] {
			continue
		}
		for _, dep := range uniqueStrings(t.Dependencies) {
			if requested[dep] {
				reverse[dep] = append(reverse[dep], t.Name)
			}
		}
	}
	return reverse
}

func allDependenciesComplete(name string, targetMap map[string]*TargetConfig, requested map[string]bool, status map[string]string) bool {
	for _, dep := range targetMap[name].Dependencies {
		if !requested[dep] {
			continue
		}
		s := status[dep]
		if s != "built" && s != "cached" {
			return false
		}
	}
	return true
}

func markSkipped(reverseDeps map[string][]string, status map[string]string, durations map[string]int64, completed *int, name string) {
	for _, dependent := range reverseDeps[name] {
		if status[dependent] == "" {
			status[dependent] = "skipped"
			durations[dependent] = 0
			*completed++
			markSkipped(reverseDeps, status, durations, completed, dependent)
		}
	}
}

func (e *buildExecutor) execute(t *TargetConfig) execResult {
	start := time.Now()
	key, err := computeCacheKey(t, e.configDir)
	if err != nil {
		return execResult{name: t.Name, status: "failed", durationMS: time.Since(start).Milliseconds(), cacheKey: key}
	}

	if !e.noCache {
		valid, _, err := cacheValid(e.cacheDir, key, t.Outputs, e.configDir)
		if err != nil {
			return execResult{name: t.Name, status: "failed", durationMS: time.Since(start).Milliseconds(), cacheKey: key}
		}
		if valid {
			return execResult{name: t.Name, status: "cached", cached: true, durationMS: time.Since(start).Milliseconds(), cacheKey: key}
		}
	}

	timeout := t.Timeout
	if timeout <= 0 {
		timeout = 300
	}

	var stdout, stderr bytes.Buffer
	cmd := exec.Command("sh", "-c", t.Command)
	cmd.Dir = e.configDir
	cmd.Env = mergedEnv(t.Env)
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}

	if err := cmd.Start(); err != nil {
		return execResult{name: t.Name, status: "failed", durationMS: time.Since(start).Milliseconds(), cacheKey: key}
	}

	waitCh := make(chan error, 1)
	go func() {
		waitCh <- cmd.Wait()
	}()

	var runErr error
	select {
	case <-time.After(time.Duration(timeout) * time.Second):
		if cmd.Process != nil {
			_ = syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
		}
		<-waitCh
		runErr = fmt.Errorf("target %q timed out after %ds", t.Name, timeout)
	case err := <-waitCh:
		if err != nil {
			runErr = err
		}
	}

	elapsed := time.Since(start).Milliseconds()
	if runErr != nil {
		if stderr.Len() > 0 {
			fmt.Fprintf(os.Stderr, "target %q stderr:\n%s", t.Name, stderr.String())
		}
		return execResult{name: t.Name, status: "failed", durationMS: elapsed, cacheKey: key}
	}

	entry := CacheEntry{
		CacheKey:   key,
		TargetName: t.Name,
		Timestamp: time.Now().UTC().Format(time.RFC3339),
		Outputs:    t.Outputs,
	}
	if err := writeCacheEntry(e.cacheDir, entry); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return execResult{name: t.Name, status: "failed", durationMS: elapsed, cacheKey: key}
	}
	return execResult{name: t.Name, status: "built", durationMS: elapsed, cacheKey: key}
}

func computeCacheKey(t *TargetConfig, configDir string) (string, error) {
	h := sha256.New()
	if _, err := io.WriteString(h, t.Command); err != nil {
		return "", err
	}

	envKeys := make([]string, 0, len(t.Env))
	for k := range t.Env {
		envKeys = append(envKeys, k)
	}
	sort.Strings(envKeys)
	for _, k := range envKeys {
		if _, err := io.WriteString(h, k+"="+t.Env[k]); err != nil {
			return "", err
		}
	}

	inputPaths := make([]string, len(t.Inputs))
	copy(inputPaths, t.Inputs)
	sort.Strings(inputPaths)
	for _, p := range inputPaths {
		contentHash, err := hashFile(resolvePath(configDir, p))
		if err != nil {
			contentHash = hashBytes(nil)
		}
		if _, err := io.WriteString(h, contentHash); err != nil {
			return "", err
		}
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

func mergedEnv(env map[string]string) []string {
	out := map[string]string{}
	for _, kv := range os.Environ() {
		parts := strings.SplitN(kv, "=", 2)
		if len(parts) == 2 {
			out[parts[0]] = parts[1]
		} else {
			out[parts[0]] = ""
		}
	}
	for k, v := range env {
		out[k] = v
	}
	result := make([]string, 0, len(out))
	for k, v := range out {
		result = append(result, k+"="+v)
	}
	sort.Strings(result)
	return result
}

func cacheValid(cacheDir, key string, outputs []string, configDir string) (bool, CacheEntry, error) {
	entry, ok, err := readCacheEntry(cacheDir, key)
	if err != nil {
		return false, CacheEntry{}, err
	}
	if !ok {
		return false, CacheEntry{}, nil
	}
	for _, out := range outputs {
		if !fileExists(resolvePath(configDir, out)) {
			return false, CacheEntry{}, nil
		}
	}
	return true, entry, nil
}

func readCacheEntry(cacheDir, key string) (CacheEntry, bool, error) {
	path := filepath.Join(cacheDir, key+".json")
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return CacheEntry{}, false, nil
	}
	if err != nil {
		return CacheEntry{}, false, err
	}
	var entry CacheEntry
	if err := json.Unmarshal(data, &entry); err != nil {
		return CacheEntry{}, false, nil
	}
	if entry.CacheKey != "" && entry.CacheKey != key {
		return CacheEntry{}, false, nil
	}
	if entry.CacheKey == "" {
		entry.CacheKey = key
	}
	return entry, true, nil
}

func writeCacheEntry(cacheDir string, entry CacheEntry) error {
	if err := os.MkdirAll(cacheDir, 0755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(entry, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(cacheDir, entry.CacheKey+".json"), data, 0644)
}

func hashFile(path string) (string, error) {
	f, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

func hashBytes(b []byte) string {
	s := sha256.Sum256(b)
	return hex.EncodeToString(s[:])
}

func resolvePath(base, p string) string {
	if filepath.IsAbs(p) {
		return p
	}
	return filepath.Join(base, p)
}

func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

func uniqueStrings(in []string) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, s := range in {
		if !seen[s] {
			seen[s] = true
			out = append(out, s)
		}
	}
	return out
}
